const WALK = new Set(['.', ',', '"', 'p', 's', 'w', 'b', 'S', 'i', 'c', '=', 'u', 'd', 'f', 'g']);
export function tileWalkable(ch) { return WALK.has(ch); }
export function tileIsWater(ch) { return ch === '~'; }
export function tileIsEncounter(ch) { return ch === '"'; }

function baseRect(g, c, x, y, w, h) { g.fillStyle = c; g.fillRect(x, y, w, h); }

function drawGrass(g, th, x, y, hash, tall = false) {
  baseRect(g, tall ? th.grassDark : th.grass, x, y, 16, 16);
  const h2 = hash2(x, y + 7);
  // subtle patches
  baseRect(g, th.grass2, x + (hash > 0.5 ? 0 : 8), y + 0, 8, 8);
  baseRect(g, th.grass2, x + (hash > 0.5 ? 8 : 0), y + 8, 8, 8);
  // blades
  const n = tall ? 7 : 3;
  for (let i = 0; i < n; i++) {
    const bx = x + 1 + Math.floor(hash2(x + i * 3, y + i) * 14);
    const by = y + 2 + Math.floor(hash2(x + i, y + i * 5) * 12);
    g.fillStyle = i % 3 === 0 ? th.blade : th.grassDark;
    g.fillRect(bx, by, 1, 2 + (i % 2));
    if (i % 2 === 0) g.fillRect(bx + 1, by + 1, 1, 1);
  }
  if (tall) {
    for (let i = 0; i < 5; i++) {
      const bx = x + 1 + Math.floor(hash2(x + i * 7, y + 3) * 14);
      g.fillStyle = th.blade;
      g.fillRect(bx, y + 5 + (i % 4), 1, 5);
    }
  }
  if (h2 > 0.93) {
    g.fillStyle = th.flower;
    g.fillRect(x + 5, y + 7, 2, 2);
    g.fillStyle = th.flower2;
    g.fillRect(x + 10, y + 11, 2, 2);
  }
}

function drawFlowers(g, th, x, y, hash) {
  drawGrass(g, th, x, y, hash);
  const c = hash > 0.5 ? th.flower : th.flower2;
  const spots = [[4, 5], [10, 8], [7, 12]];
  spots.forEach(([fx, fy], i) => {
    g.fillStyle = c; g.fillRect(x + fx, y + fy, 2, 2);
    g.fillStyle = '#fff6d8'; g.fillRect(x + fx, y + fy, 1, 1);
  });
}

function drawPath(g, th, x, y, hash) {
  baseRect(g, th.path, x, y, 16, 16);
  baseRect(g, th.path2, x, y + 8, 16, 8);
  g.fillStyle = th.pathDark;
  g.fillRect(x, y, 16, 1); g.fillRect(x, y + 15, 16, 1);
  if (hash > 0.55) {
    g.fillStyle = th.pebble;
    g.fillRect(x + Math.floor(hash * 12) + 2, y + Math.floor(hash2(x, y) * 12) + 2, 2, 2);
  }
  if (hash > 0.85) { g.fillStyle = th.pathDark; g.fillRect(x + 3, y + 9, 3, 1); }
}

function drawStoneFloor(g, th, x, y, hash, dark = false) {
  const base = dark ? th.stone2 : th.stone;
  const line = th.stone2;
  baseRect(g, base, x, y, 16, 16);
  g.fillStyle = line;
  g.fillRect(x, y + 15, 16, 1); g.fillRect(x + 15, y, 1, 16);
  g.fillRect(x, y + 7, 16, 1); g.fillRect(x + 7, y, 1, 7); g.fillRect(x + 11, y + 8, 1, 7);
  g.fillStyle = 'rgba(255,255,255,.06)';
  g.fillRect(x + 1, y + 1, 6, 1); g.fillRect(x + 12, y + 9, 3, 1);
  if (hash > 0.8) { g.fillStyle = line; g.fillRect(x + 3, y + 10, 4, 1); }
}

function drawWood(g, th, x, y, hash) {
  baseRect(g, th.wood, x, y, 16, 16);
  g.fillStyle = th.wood2;
  g.fillRect(x, y + 3, 16, 1); g.fillRect(x, y + 7, 16, 1); g.fillRect(x, y + 11, 16, 1); g.fillRect(x, y + 15, 16, 1);
  g.fillStyle = 'rgba(255,255,255,.07)';
  g.fillRect(x + 2, y + 1, 5, 1); g.fillRect(x + 9, y + 5, 5, 1);
  g.fillStyle = th.wood2;
  g.fillRect(x + 4, y + 4, 1, 3); g.fillRect(x + 11, y + 8, 1, 3); g.fillRect(x + 7, y + 12, 1, 3);
}

function drawWater(g, th, x, y, hash, time = 0) {
  baseRect(g, th.water, x, y, 16, 16);
  baseRect(g, th.water2, x, y + 4, 16, 8);
  g.fillStyle = th.waterLight;
  const w1 = 3 + Math.floor(hash * 5);
  g.globalAlpha = 0.35;
  g.fillRect(x + 2, y + 3, w1, 1);
  g.fillRect(x + 9, y + 8, 4, 1);
  g.fillRect(x + 4, y + 12, 5, 1);
  g.globalAlpha = 1;
}

function drawBridge(g, th, x, y, hash) {
  baseRect(g, th.wood, x, y, 16, 16);
  g.fillStyle = th.wood2;
  for (let i = 0; i < 4; i++) g.fillRect(x + 1, y + i * 4 + 3, 14, 1);
  g.fillStyle = '#3a3a3a';
  g.fillRect(x, y, 2, 16); g.fillRect(x + 14, y, 2, 16);
  g.fillStyle = '#6a6a6a';
  g.fillRect(x + 1, y + 1, 1, 1); g.fillRect(x + 1, y + 13, 1, 1);
}

function drawSnow(g, th, x, y, hash) {
  baseRect(g, th.grass, x, y, 16, 16);
  baseRect(g, th.grass2, x + (hash > 0.5 ? 0 : 8), y, 8, 16);
  g.fillStyle = th.grassDark;
  g.globalAlpha = 0.25;
  g.fillRect(x + 1, y + 12, 6, 1); g.fillRect(x + 9, y + 5, 4, 1);
  g.globalAlpha = 1;
  if (hash > 0.9) { g.fillStyle = '#ffffff'; g.fillRect(x + 4, y + 6, 2, 2); g.fillRect(x + 11, y + 11, 1, 1); }
  g.fillStyle = 'rgba(160,200,230,.18)';
  g.fillRect(x + 2, y + 2, 2, 2);
}

function drawIce(g, th, x, y, hash) {
  baseRect(g, '#b8d8e8', x, y, 16, 16);
  baseRect(g, '#c8e4f2', x, y + 6, 16, 10);
  g.fillStyle = '#8ab8d0';
  g.fillRect(x + 3, y + 4, 1, 5); g.fillRect(x + 4, y + 8, 4, 1);
  g.fillRect(x + 10, y + 2, 1, 6); g.fillRect(x + 8, y + 7, 3, 1);
  g.fillStyle = '#eefaff';
  g.fillRect(x + 6, y + 10, 3, 1);
}

function drawCarpet(g, th, x, y, hash) {
  baseRect(g, '#5a1e2a', x, y, 16, 16);
  baseRect(g, '#6e2634', x + 2, y, 12, 16);
  g.fillStyle = '#c9a44c';
  g.fillRect(x, y, 2, 16); g.fillRect(x + 14, y, 2, 16);
  g.fillStyle = '#8a3040';
  g.fillRect(x + 5, y + 4, 6, 1); g.fillRect(x + 5, y + 11, 6, 1);
  g.fillStyle = '#e0c070';
  if ((x / 16 + y / 16) % 2 === 0) { g.fillRect(x + 7, y + 7, 2, 2); }
}

function drawWall(g, th, x, y, hash) {
  baseRect(g, th.wall2, x, y, 16, 16);
  // brick courses
  g.fillStyle = th.wall;
  for (let row = 0; row < 4; row++) {
    const off = (row % 2) * 4;
    for (let col = -1; col < 3; col++) {
      const bx = x + col * 8 + off;
      const by = y + row * 4;
      g.fillRect(Math.max(x, bx + 1), by + 1, Math.min(7, x + 16 - Math.max(x, bx + 1)), 3);
    }
  }
  g.fillStyle = 'rgba(255,255,255,.06)';
  g.fillRect(x + 1, y + 1, 6, 1);
  if (hash > 0.75) { g.fillStyle = 'rgba(0,0,0,.18)'; g.fillRect(x + 9, y + 9, 5, 2); }
}

function drawDungeon(g, th, x, y, hash) {
  baseRect(g, '#3a3a40', x, y, 16, 16);
  baseRect(g, '#34343a', x, y + 8, 16, 8);
  g.fillStyle = '#2a2a30';
  g.fillRect(x, y + 15, 16, 1); g.fillRect(x + 15, y, 1, 16); g.fillRect(x + 7, y, 1, 8);
  if (hash > 0.7) { g.fillStyle = '#4a4a50'; g.fillRect(x + 3, y + 4, 4, 1); }
  if (hash > 0.9) { g.fillStyle = '#4a5a3a'; g.fillRect(x + 10, y + 11, 3, 2); }
}

function drawDirt(g, th, x, y, hash) {
  baseRect(g, th.path2, x, y, 16, 16);
  g.fillStyle = th.pathDark;
  g.fillRect(x + 2, y + 6, 3, 1); g.fillRect(x + 10, y + 12, 4, 1);
  g.fillStyle = th.pebble;
  if (hash > 0.6) g.fillRect(x + 6, y + 3, 1, 1);
}

function drawVoid(g, x, y) { baseRect(g, '#04060a', x, y, 16, 16); }

export function renderGround(map) {
  const th = THEMES[map.theme] || THEMES.village;
  const { c, g } = makeCanvas(map.w * 16, map.h * 16);
  g.imageSmoothingEnabled = false;
  for (let y = 0; y < map.h; y++) {
    const row = map.ground[y] || '';
    for (let x = 0; x < map.w; x++) {
      const ch = row[x] || '#';
      const px = x * 16, py = y * 16;
      const hash = hash2(x * 3 + 1, y * 5 + 2);
      switch (ch) {
        case '.': drawGrass(g, th, px, py, hash); break;
        case ',': drawFlowers(g, th, px, py, hash); break;
        case '"': drawGrass(g, th, px, py, hash, true); break;
        case 'p': drawPath(g, th, px, py, hash); break;
        case 's': drawStoneFloor(g, th, px, py, hash, false); break;
        case '=': drawStoneFloor(g, th, px, py, hash, true); break;
        case 'w': drawWood(g, th, px, py, hash); break;
        case '~': drawWater(g, th, px, py, hash); break;
        case 'b': drawBridge(g, th, px, py, hash); break;
        case 'S': drawSnow(g, th, px, py, hash); break;
        case 'i': drawIce(g, th, px, py, hash); break;
        case 'c': drawCarpet(g, th, px, py, hash); break;
        case '#': drawWall(g, th, px, py, hash); break;
        case 'u': drawDungeon(g, th, px, py, hash); break;
        case 'd': drawDirt(g, th, px, py, hash); break;
        case 'f': drawGrass(g, th, px, py, hash, true); break;
        case 'X': drawVoid(g, px, py); break;
        default: drawGrass(g, th, px, py, hash);
      }
    }
  }
  // soft ambient overlays
  if (th.dark) {
    g.fillStyle = 'rgba(4,8,20,.18)';
    g.fillRect(0, 0, c.width, c.height);
  }
  if (map.theme === 'forest') {
    g.fillStyle = 'rgba(30,60,30,.10)';
    g.fillRect(0, 0, c.width, c.height);
  }
  return c;
}

export function drawWaterShimmer(g, map, cam, time, zoom) {
  const th = THEMES[map.theme] || THEMES.village;
  const x0 = Math.max(0, Math.floor(cam.x / 16));
  const y0 = Math.max(0, Math.floor(cam.y / 16));
  const x1 = Math.min(map.w - 1, Math.ceil((cam.x + cam.w) / 16));
  const y1 = Math.min(map.h - 1, Math.ceil((cam.y + cam.h) / 16));
  g.save();
  g.globalAlpha = 0.35;
  g.fillStyle = th.waterLight;
  for (let y = y0; y <= y1; y++) {
    const row = map.ground[y] || '';
    for (let x = x0; x <= x1; x++) {
      if (row[x] !== '~') continue;
      const phase = hash2(x, y) * 6.28;
      const off = Math.sin(time * 1.8 + phase) * 3;
      const wx = (x * 16 + 3 + off) * zoom - cam.x * zoom;
      const wy = (y * 16 + 6 + Math.cos(time * 1.2 + phase) * 2) * zoom - cam.y * zoom;
      g.fillRect(Math.round(wx), Math.round(wy), 5 * zoom, Math.max(1, Math.round(zoom * 0.7)));
    }
  }
  g.restore();
}

// art/props.js — town buildings, nature, furniture and dungeon decor
import { THEMES } from './tiles.js';
import { hash2 } from '../util.js';

export const PROP_DEFS = {
  house:   { w: 6, h: 4, solid: true, tall: true },
  hut:     { w: 4, h: 3, solid: true, tall: true },
  tower:   { w: 4, h: 5, solid: true, tall: true },
  tree:    { w: 2, h: 2, solid: true, baseOnly: true, tall: true },
  pine:    { w: 2, h: 2, solid: true, baseOnly: true, tall: true },
  deadtree:{ w: 1, h: 1, solid: true, tall: true },
  rock:    { w: 1, h: 1, solid: true },
  bush:    { w: 1, h: 1, solid: false },
  fence:   { w: 1, h: 1, solid: true },
  lamp:    { w: 1, h: 1, solid: true, tall: true },
  well:    { w: 2, h: 2, solid: true, tall: true },
  stall:   { w: 3, h: 2, solid: true, tall: true },
  crate:   { w: 1, h: 1, solid: true },
  barrel:  { w: 1, h: 1, solid: true },
  sign:    { w: 1, h: 1, solid: true, tall: true },
  grave:   { w: 1, h: 1, solid: true, tall: true },
  statue:  { w: 2, h: 2, solid: true, tall: true },
  pillar:  { w: 1, h: 2, solid: true, tall: true },
  throne:  { w: 3, h: 3, solid: true, tall: true },
  altar:   { w: 3, h: 2, solid: true, tall: true },
  campfire:{ w: 2, h: 2, solid: true, tall: true },
  banner:  { w: 1, h: 2, solid: true, tall: true },
  fountain:{ w: 3, h: 3, solid: true, tall: true },
  dummy:   { w: 1, h: 1, solid: true, tall: true },
  tent:    { w: 3, h: 2, solid: true, tall: true },
  gate:    { w: 4, h: 2, solid: true, tall: true },
  stairs:  { w: 2, h: 2, solid: false, tall: true },
  rubble:  { w: 1, h: 1, solid: true },
  crystal: { w: 1, h: 1, solid: true, tall: true },
  torch:   { w: 1, h: 1, solid: true, tall: true },
  table:   { w: 2, h: 1, solid: true },
  bed:     { w: 2, h: 2, solid: true },
  shelf:   { w: 2, h: 1, solid: true, tall: true },
  door:    { w: 1, h: 1, solid: false, tall: true },
  portal:  { w: 2, h: 2, solid: false, tall: true },
  treeSnow:{ w: 2, h: 2, solid: true, baseOnly: true, tall: true },
  pineSnow:{ w: 2, h: 2, solid: true, baseOnly: true, tall: true },
};

export function propSize(p) {
  const d = PROP_DEFS[p.t] || { w: 1, h: 1 };
  return { w: p.w ?? d.w, h: p.h ?? d.h };
}

export function propBaseY(p) {
  const s = propSize(p);
  return (p.y + s.h) * 16;
}

export function propSolidRect(p) {
  const s = propSize(p);
  const d = PROP_DEFS[p.t] || {};
  if (d.solid === false) return null;
  if (d.baseOnly) return { x: p.x, y: p.y + s.h - 1, w: s.w, h: 1 };
  return { x: p.x, y: p.y, w: s.w, h: s.h };
}

function rect(g, c, x, y, w, h) { g.fillStyle = c; g.fillRect(x, y, w, h); }
function poly(g, c, pts) {
  g.fillStyle = c; g.beginPath();
  pts.forEach(([x, y], i) => i ? g.lineTo(x, y) : g.moveTo(x, y));
  g.closePath(); g.fill();
}
function shadow(g, x, y, rx, ry, a = 0.32) {
  g.fillStyle = `rgba(0,0,0,${a})`;
  g.beginPath(); g.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2); g.fill();
}

function drawHouse(g, p, th, time, o) {
  const s = propSize(p);
  const W = s.w * 16, H = s.h * 16, x = p.x * 16, y = p.y * 16;
  const roofC = p.v === 'blue' ? '#3e5678' : p.v === 'thatch' ? '#8a7038' : th.roof;
  const roofD = p.v === 'blue' ? '#2a3c58' : p.v === 'thatch' ? '#6a5428' : th.roof2;
  shadow(g, x + W / 2, y + H - 3, W * 0.55, 6, 0.36);
  const wallTop = y + H * 0.36;
  // wall
  rect(g, th.plaster, x + 5, wallTop, W - 10, H - (wallTop - y) - 3);
  rect(g, th.wall2, x + 5, wallTop, W - 10, 2);
  // timber frame
  g.fillStyle = th.wood2;
  g.fillRect(x + 5, wallTop + 10, W - 10, 2);
  g.fillRect(x + 10, wallTop, 3, H - (wallTop - y) - 3);
  g.fillRect(x + W - 13, wallTop, 3, H - (wallTop - y) - 3);
  g.fillRect(x + W / 2 - 2, wallTop + 10, 3, H - (wallTop - y) - 12);
  // roof
  const over = 7;
  poly(g, roofD, [[x - over, y + H * 0.40], [x + 8, y - 12], [x + W - 8, y - 12], [x + W + over, y + H * 0.40]]);
  poly(g, roofC, [[x - over + 2, y + H * 0.39], [x + 9, y - 10], [x + W - 9, y - 10], [x + W + over - 2, y + H * 0.39]]);
  // shingles
  g.fillStyle = roofD;
  for (let i = 0; i < 5; i++) {
    const yy = y - 6 + i * (H * 0.44 / 5);
    g.fillRect(x + 4 + i * 2, yy, W - 8 - i * 4, 1);
  }
  g.fillStyle = 'rgba(255,255,255,.12)';
  g.fillRect(x + 12, y - 9, W - 24, 2);
  // chimney
  const chx = x + W - 20;
  rect(g, '#5a4a44', chx, y - 24, 9, 20);
  rect(g, '#6e5c54', chx + 1, y - 23, 7, 2);
  rect(g, '#3a2e2a', chx + 2, y - 25, 5, 2);
  if (time != null) {
    g.globalAlpha = 0.18;
    for (let i = 0; i < 4; i++) {
      const t = (time * 0.35 + i * 0.25 + (p.x * 0.13)) % 1;
      g.fillStyle = '#c8c8d0';
      g.beginPath();
      g.arc(chx + 4 + Math.sin(t * 5 + p.x) * 5, y - 28 - t * 34, 3 + t * 5, 0, Math.PI * 2);
      g.fill();
    }
    g.globalAlpha = 1;
  }
  // door
  const dx = x + W / 2 - 7;
  rect(g, th.wood2, dx - 2, y + H - 22, 18, 20);
  rect(g, '#4a2e1a', dx, y + H - 20, 14, 18);
  rect(g, '#6e4728', dx + 1, y + H - 19, 12, 17);
  g.fillStyle = '#c9a44c'; g.fillRect(dx + 10, y + H - 11, 2, 2);
  // windows
  const glow = th.dark ? '#ffcf7a' : '#7a9aac';
  const wxs = [x + 14, x + W - 30];
  wxs.forEach((wx) => {
    rect(g, '#3a2a1e', wx - 2, wallTop + 16, 16, 14);
    rect(g, glow, wx, wallTop + 18, 12, 10);
    g.fillStyle = 'rgba(255,255,255,.35)'; g.fillRect(wx + 1, wallTop + 19, 4, 2);
    g.fillStyle = '#3a2a1e'; g.fillRect(wx + 5, wallTop + 18, 1, 10); g.fillRect(wx, wallTop + 22, 12, 1);
    if (th.dark) {
      g.save(); g.globalCompositeOperation = 'lighter'; g.globalAlpha = 0.1;
      g.fillStyle = '#ffb860'; g.beginPath(); g.arc(wx + 6, wallTop + 23, 16, 0, Math.PI * 2); g.fill(); g.restore();
    }
  });
  // flowers by door
  g.fillStyle = th.flower;
  g.fillRect(dx - 6, y + H - 5, 2, 2); g.fillRect(dx + 20, y + H - 6, 2, 2);
}

function drawTree(g, p, th, time, snowy) {
  const s = propSize(p);
  const cx = p.x * 16 + s.w * 8, base = (p.y + s.h) * 16;
  const phase = hash2(p.x, p.y) * 6.28;
  const sway = Math.round(Math.sin(time * 0.8 + phase) * 1);
  shadow(g, cx, base - 1, 12, 4, 0.3);
  // trunk
  rect(g, '#4a3220', cx - 3, base - 18, 6, 18);
  rect(g, '#5c4028', cx - 2, base - 17, 3, 15);
  const g1 = snowy ? '#d8e8f0' : th.grassDark;
  const g2 = snowy ? '#e8f4fa' : th.grass2;
  const g3 = snowy ? '#ffffff' : th.blade;
  const cy = base - 32;
  const blobs = [[-9, 2, 10], [9, 2, 10], [0, -7, 12], [-3, 9, 11], [4, 8, 10]];
  g.fillStyle = g1;
  blobs.forEach(([bx, by, r]) => { g.beginPath(); g.arc(cx + bx + sway, cy + by, r, 0, Math.PI * 2); g.fill(); });
  g.fillStyle = g2;
  blobs.forEach(([bx, by, r]) => { g.beginPath(); g.arc(cx + bx + sway - 1, cy + by - 2, r - 3, 0, Math.PI * 2); g.fill(); });
  g.fillStyle = g3;
  g.beginPath(); g.arc(cx - 4 + sway, cy - 6, 5, 0, Math.PI * 2); g.fill();
  g.beginPath(); g.arc(cx + 7 + sway, cy + 4, 3, 0, Math.PI * 2); g.fill();
  if (snowy) {
    g.fillStyle = '#ffffff';
    g.beginPath(); g.arc(cx - 7 + sway, cy - 3, 4, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.arc(cx + 8 + sway, cy + 1, 3, 0, Math.PI * 2); g.fill();
  }
}

function drawPine(g, p, th, time, snowy) {
  const s = propSize(p);
  const cx = p.x * 16 + s.w * 8, base = (p.y + s.h) * 16;
  const phase = hash2(p.x, p.y) * 6.28;
  const sway = Math.round(Math.sin(time * 0.7 + phase) * 1);
  shadow(g, cx, base - 1, 11, 4, 0.3);
  rect(g, '#4a3220', cx - 2, base - 14, 4, 14);
  const c1 = snowy ? '#4a6a6a' : th.grassDark;
  const c2 = snowy ? '#6a8a8a' : th.grass2;
  const c3 = snowy ? '#ffffff' : th.blade;
  for (let i = 0; i < 4; i++) {
    const yy = base - 16 - i * 10;
    const w = 20 - i * 4;
    poly(g, c1, [[cx - w, yy], [cx + w, yy], [cx + sway, yy - 18]]);
    poly(g, c2, [[cx - w + 4, yy - 1], [cx + w - 4, yy - 1], [cx + sway, yy - 15]]);
    if (snowy) poly(g, c3, [[cx - w + 5, yy - 2], [cx + w - 5, yy - 2], [cx + sway, yy - 12]]);
    else { g.fillStyle = c3; g.fillRect(cx - 3 + sway, yy - 12, 2, 3); }
  }
}

function drawRock(g, p, th, time, snowy) {
  const x = p.x * 16, y = p.y * 16;
  shadow(g, x + 8, y + 14, 7, 3, 0.3);
  const base = snowy ? '#9aa8b8' : '#5e6670';
  const hi = snowy ? '#d8e4ee' : '#79828e';
  const dk = snowy ? '#7a8898' : '#454c56';
  poly(g, dk, [[x + 1, y + 14], [x + 3, y + 6], [x + 7, y + 2], [x + 13, y + 5], [x + 15, y + 12], [x + 12, y + 15], [x + 4, y + 15]]);
  poly(g, base, [[x + 3, y + 12], [x + 5, y + 6], [x + 9, y + 4], [x + 13, y + 7], [x + 13, y + 12], [x + 9, y + 13]]);
  g.fillStyle = hi; g.fillRect(x + 6, y + 5, 4, 2); g.fillRect(x + 9, y + 7, 2, 1);
  if (snowy) { g.fillStyle = '#fff'; g.fillRect(x + 6, y + 3, 5, 2); }
}

function drawBush(g, p, th) {
  const x = p.x * 16, y = p.y * 16;
  shadow(g, x + 8, y + 14, 6, 2, 0.25);
  g.fillStyle = th.grassDark;
  g.beginPath(); g.arc(x + 8, y + 10, 7, 0, Math.PI * 2); g.fill();
  g.fillStyle = th.grass2;
  g.beginPath(); g.arc(x + 7, y + 9, 5, 0, Math.PI * 2); g.fill();
  g.fillStyle = th.blade;
  g.fillRect(x + 4, y + 6, 2, 2);
  if (hash2(p.x, p.y) > 0.5) {
    g.fillStyle = '#c94a5a'; g.fillRect(x + 10, y + 8, 2, 2); g.fillRect(x + 6, y + 11, 2, 2);
  }
}

function drawFence(g, p, th) {
