    ctx.levelTo('garrick', 10);
    ctx.levelTo('mira', 10);
    ctx.levelTo('lyra', 10);
    ctx.healAll(1);
    await lines([
      ['Narrador', 'O último cavaleiro sombrio se desfaz. A porta do trono se abre sozinha.'],
