23: async function finalBattle(g, ctx) {
24:   if (g.flags.finalStarted) return;
25:   set(g, 'finalStarted');
26:   await lines([
27:     ['Dorian', 'Aí está. O lenhador que virou lenda. A lenda que virou praga.'],
28:     ['Kael', 'Acabou, Dorian.'],
29:     ['Dorian', 'Acabou? Eu peguei um reino faminto e dei a ele um inimigo. Peguei uma garota assustada e dei a ela um propósito. Você só sabe destruir.'],
30:     ['Lyra', 'Você me deu uma corrente e chamou de propósito.'],
31:     ['Dorian', 'Lyra. Ainda defendendo o homem que te esqueceu?'],
32:     ['Kael', 'Eu nunca esqueci. Só parei de correr atrás do passado.'],
33:     ['Dorian', 'Então me mostre o futuro.'],
34:   ]);
35:   await fight(g, ctx, ['dorian', 'wraith'], {
36:     boss: true, bg: 'castle', canFlee: false,
37:     intro: 'Dorian ergue a Brasa Eterna. O trono se incendeia.',
38:   });
39:   set(g, 'dorianDown');
40:   await lines([
41:     ['Dorian', 'Você... ainda não entende. A Brasa não pode ser apagada. Ela só troca de dono.'],
42:     ['Lyra', 'Então eu serei a última.'],
43:     ['Narrador', 'Lyra segura a Lâmina Aurora. A Brasa Eterna grita — um som que atravessa pedra, carne e memória. E então... silêncio.'],
44:     ['Dorian', 'Eu só queria... que alguém lembrasse de mim.'],
45:     ['Kael', 'Eu lembro. É por isso que não vou te perdoar.'],
46:   ]);
47:   const choice = await ui.choice('O que Kael leva consigo?', [
48:     { label: 'Perdoar Lyra. Recomeçar.', value: 'forgive' },
49:     { label: 'Seguir em frente. Sozinho.', value: 'leave' },
50:   ]);
51:   set(g, 'forgaveLyra', choice === 'forgive');
52:   set(g, 'completed');
53:   g.completed = true;
54:   await ui.ending(g);
55:   return 'title';
56: }
