108: function loadGame(save) {
109:   if (!save || save.version !== 1 || !Array.isArray(save.party) || !save.party.length) return false;
110:   game = {
111:     ...save,
112:     flags: save.flags || {},
113:     triggers: save.triggers || {},
114:     chests: save.chests || {},
115:     seen: save.seen || {},
116:     inventory: save.inventory || {},
117:     journal: save.journal || [],
118:     party: save.party,
119:     chapter: save.chapter || 0,
120:     gold: save.gold || 0,
121:     quest: save.quest || 'Encontre um caminho adiante.',
122:     playTime: save.playTime || 0,
123:     battlesWon: save.battlesWon || 0,
124:     completed: !!save.completed,
125:   };
126:   for (const m of game.party) {
127:     m.status = {};
128:     m.buffs = [];
129:     m.defending = false;
130:     m.hp = clamp(Number(m.hp) || 0, 0, m.maxHp);
131:     m.mp = clamp(Number(m.mp) || 0, 0, m.maxMp);
132:     if (!m.skills) m.skills = [];
133:   }
134:   const map = getMap(save.mapId) || MAPS.village;
135:   const p = save.player || {};
136:   setMap(map.id, Number.isFinite(p.x) ? p.x : map.spawn.x, Number.isFinite(p.y) ? p.y : map.spawn.y, p.dir || map.spawn.dir);
137:   game.chapterLabel = `Capítulo ${CHAPTERS[game.chapter]?.n || 'I'}`;
138:   game.playTimeLabel = formatTime(game.playTime);
139:   ui.updateHUD(game);
140:   return true;
141: }
