193: function solidAt(tx, ty) {
194:   if (!currentMap) return true;
195:   if (tx < 0 || ty < 0 || tx >= currentMap.w || ty >= currentMap.h) return true;
196:   const ch = (currentMap.ground[ty] || '')[tx];
197:   if (!tileWalkable(ch)) return true;
198: 
199:   for (const p of currentMap.props) {
200:     const r = propSolidRect(p);
201:     if (!r) continue;
202:     if (p.openFlag && game.flags[p.openFlag]) continue;
203:     if (tx >= r.x && tx < r.x + r.w && ty >= r.y && ty < r.y + r.h) return true;
204:   }
205:   for (const n of currentMap.npcs) {
206:     if (!npcPresent(n)) continue;
207:     if (n.x === tx && n.y === ty) return true;
208:   }
209:   for (const c of currentMap.chests) {
210:     if (!chestPresent(c)) continue;
211:     if (c.x === tx && c.y === ty) return true;
212:   }
213:   return false;
214: }
