216: function tryMove(dir) {
217:   const [dx, dy] = DIRV[dir];
218:   const nx = player.x + dx;
219:   const ny = player.y + dy;
220:   if (solidAt(nx, ny)) {
221:     player.bump = 0.12;
222:     return;
223:   }
224:   player.fromX = player.x;
225:   player.fromY = player.y;
226:   player.x = nx;
227:   player.y = ny;
228:   player.moving = true;
229:   player.t = 0;
230:   stepSound++;
231:   if (stepSound % 2 === 0) audio.sfx('step');
232: }
