234: function onStepComplete() {
235:   if (mode !== 'explore' || isBusy()) return;
236:   if (checkTriggers()) return;
237:   if (checkPortals()) return;
238:   checkEncounter();
239: }
240: 
241: function checkPortals() {
242:   if (transitioning) return false;
243:   for (const p of currentMap.portals) {
244:     if (p.when && !p.when(game)) continue;
245:     if (!inRect(player.x, player.y, p)) continue;
246:     audio.sfx('door');
247:     gotoMap(p.to, p.tx, p.ty, p.dir || 'up');
248:     return true;
249:   }
250:   return false;
251: }
252: 
253: function checkTriggers() {
254:   for (const t of currentMap.triggers) {
255:     if (game.triggers[t.id]) continue;
256:     if (t.when && !t.when(game)) continue;
257:     if (!inRect(player.x, player.y, t)) continue;
258:     game.triggers[t.id] = true;
259:     runStory(t.script);
260:     return true;
261:   }
262:   return false;
263: }
264: 
265: function checkEncounter() {
266:   const enc = currentMap.encounter;
267:   if (!enc) return;
268:   const ch = (currentMap.ground[player.y] || '')[player.x];
269:   if (!enc.tiles.includes(ch)) return;
270:   encounterSteps++;
271:   if (encounterSteps < (enc.minSteps || 10)) return;
272:   if (!chance(enc.rate || 0.05)) return;
273:   encounterSteps = 0;
274:   const groups = ENCOUNTERS[enc.groups] || [];
275:   if (!groups.length) return;
276:   const group = pick(groups);
277:   runBattle(group, { bg: currentMap.theme, intro: 'Uma emboscada no caminho!' }).then((res) => {
278:     if (res === 'title') endSession('title');
279:   });
280: }
