308: // ------------------------------------------------------------------ interaction
309: function interact() {
310:   if (!player || mode !== 'explore' || isBusy()) return;
311:   const [dx, dy] = DIRV[player.dir];
312:   const tx = player.x + dx;
313:   const ty = player.y + dy;
314: 
315:   const npc = currentMap.npcs.find((n) => npcPresent(n) && n.x === tx && n.y === ty);
316:   if (npc) {
317:     audio.sfx('confirm');
318:     if (npc.talk && hasScript(npc.talk)) runStory(npc.talk);
319:     else ui.say(npc.name || 'Narrador', '...');
320:     return;
321:   }
322: 
323:   const chest = currentMap.chests.find((c) => chestPresent(c) && c.x === tx && c.y === ty);
324:   if (chest) { openChest(chest); return; }
325: 
326:   const prop = currentMap.props.find((p) => p.x === tx && p.y === ty && p.t === 'sign');
327:   if (prop) {
328:     audio.sfx('confirm');
329:     ui.say('Narrador', 'A placa está gasta pelo tempo. Resta apenas uma palavra: “Aurora”.');
330:   }
331: }
