405: let storyId = 0;
406: async function runStory(name) {
407:   if (!name) return;
408:   const blocker = `story-${++storyId}`;
409:   block(blocker);
410:   try {
411:     const result = await runScript(name, game, storyCtx);
412:     if (result === 'title') {
413:       if (game.completed) saveGame(true);
414:       endSession('title');
415:       return;
416:     }
417:     if (!sessionEnded) saveGame(true);
418:   } catch (err) {
419:     if (err === TITLE_EXIT) { endSession('title'); return; }
420:     console.error('Story error:', name, err);
421:   } finally {
422:     unblock(blocker);
423:   }
424: }
