449: async function runBattle(ids, opts = {}) {
450:   if (mode === 'battle') return 'ok';
451:   mode = 'battle';
452:   Input.exploreAction = null;
453:   ui.setTouchVisible(false);
454:   const bg = opts.bg || currentMap?.theme || 'forest';
455:   try {
456:     const res = await startBattle(game, ids, { ...opts, bg });
457:     if (res === 'title') { endSession('title'); return 'title'; }
458:     return res;
459:   } finally {
460:     if (!sessionEnded) {
461:       mode = 'explore';
462:       Input.exploreAction = exploreAction;
463:       ui.setTouchVisible(true);
464:       if (currentMap) audio.playMusic(currentMap.bgm || 'field');
465:       ui.updateHUD(game);
466:       saveGame(true);
467:     }
468:   }
469: }
